      for (const choice of node.choices || []) { if (choice.id) { addId(choice.id, `選択肢（${node.id}）`); } else warnings.push(`ノード「${node.id}」の選択肢にIDがありません`); }
      if (node.routes?.length && (node.text || node.speakerId || node.choices || node.nextNodeId)) warnings.push(`分岐専用ノード「${node.id}」には本文・話者・通常遷移を設定しないでください`);
