  for (const hint of scenario.hints || []) for (const stage of hint.stages || []) { addId(stage.id, 'ヒント段階'); }
  for (const item of [...(scenario.evidence || []), ...(scenario.logs || []), ...(scenario.hints || []), ...(scenario.events || []), ...allInteractions().map((x) => x.graph)]) for (const cond of [item.requires]) if (cond?.type === 'conversation' && cond.targetId && !graphTargets.has(cond.targetId)) errors.push(`条件の会話「${cond.targetId}」が見つかりません`);
